from decimal import Decimal, getcontext
getcontext().prec = 40  # Set precision for high accuracy

def solve(payload):
    # Validate input
    if 'components' not in payload or not isinstance(payload['components'], list):
        return {'valid': False, 'reason': 'unsupported_component_count'}

    components = payload['components']
    valid_components = []
    standard_unicertainties = []
    sensitivity_coefficients = []

    for comp in components:
        if not isinstance(comp, dict):
            return {'valid': False, 'reason': 'invalid_component'}

        if 'type' not in comp or 'sensitivity' not in comp:
            return {'valid': False, 'reason': 'invalid_component'}

        if comp['type'] not in ['type_a', 'type_b']:
            return {'valid': False, 'reason': 'invalid_component_kind'}

        if comp['type'] == 'type_a':
            if 'observations' not in comp or not isinstance(comp['observations'], list):
                return {'valid': False, 'reason': 'invalid_component'}
            observations = comp['observations']
            if len(observations) < 2:
                return {'valid': False, 'reason': 'type_a_requires_two_observations'}
            try:
                sum_obs = Decimal('0')
                for obs in observations:
                    sum_obs += Decimal(str(obs))
                mean = sum_obs / Decimal(len(observations))
                sum_sq_dev = Decimal('0')
                for obs in observations:
                    dev = Decimal(str(obs)) - mean
                    sum_sq_dev += dev * dev
                sample_std = (sum_sq_dev / (Decimal(len(observations)) - 1)).sqrt()
                standard_unicertainty = sample_std / Decimal(len(observations)).sqrt()
            except:
                return {'valid': False, 'reason': 'invalid_component'}

        elif comp['type'] == 'type_b':
            if 'half_width' not in comp:
                return {'valid': False, 'reason': 'invalid_component'}
            half_width = Decimal(str(comp['half_width']))
            if half_width < 0:
                return {'valid': False, 'reason': 'negative_half_width'}
            standard_unicertainty = half_width / Decimal(3).sqrt()

        # Convert sensitivity to Decimal
        try:
            sensitivity = Decimal(str(comp['sensitivity']))
        except:
            return {'valid': False, 'reason': 'invalid_sensitivity'}

        valid_components.append({
            'type': comp['type'],
            'sensitivity': float(sensitivity),
            'standard_unicertainty': float(standard_unicertainty)
        })
        standard_unicertainties.append(float(standard_unicertainty))
        sensitivity_coefficients.append(float(sensitivity))

    # Handle correlation matrix
    if 'correlation_matrix' in payload:
        correlation_matrix = payload['correlation_matrix']
        if not isinstance(correlation_matrix, list) or len(correlation_matrix) != len(components):
            return {'valid': False, 'reason': 'invalid_correlation_matrix'}
        for row in correlation_matrix:
            if not isinstance(row, list) or len(row) != len(components):
                return {'valid': False, 'reason': 'invalid_correlation_matrix'}
            for val in row:
                if not isinstance(val, (int, float, Decimal)):
                    return {'valid': False, 'reason': 'invalid_correlation_matrix'}
    else:
        n = len(components)
        correlation_matrix = [[0.0 for _ in range(n)] for _ in range(n)]
        for i in range(n):
            correlation_matrix[i][i] = 1.0

    # Calculate combined variance
    n = len(components)
    combined_variance = Decimal('0')
    for i in range(n):
        for j in range(n):
            rho_ij = Decimal(str(correlation_matrix[i][j]))
            u_i = standard_unicertainties[i]
            u_j = standard_unicertainties[j]
            c_i = sensitivity_coefficients[i]
            c_j = sensitivity_coefficients[j]
            term = Decimal(c_i) * Decimal(c_j) * Decimal(u_i) * Decimal(u_j) * rho_ij
            combined_variance += term

    if combined_variance < 0:
        return {'valid': False, 'reason': 'non_psd_correlation_matrix'}

    combined_u = combined_variance.sqrt()

    # Handle coverage factor
    if 'coverage_factor' not in payload or not isinstance(payload['coverage_factor'], (int, float, Decimal)):
        return {'valid': False, 'reason': 'missing_coverage_factor'}
    coverage_factor = Decimal(str(payload['coverage_factor']))
    if coverage_factor < 0:
        return {'valid': False, 'reason': 'invalid_coverage_factor'}

    expanded_u = combined_u * coverage_factor

    result = {
        'valid': True,
        'uncertainties': [float(comp['standard_unicertainty']) for comp in valid_components],
        'combined_uncertainty': float(combined_u),
        'expanded_uncertainty': float(expanded_u)
    }

    return result
```

